  1→// BridgeComponent.h
  2→// Claude Code → UE5.7 File-Based Bridge
  3→// Part of "The Translators" cognitive profiling game
  4→//
  5→// This component watches ~/.translators/ for file changes and handles:
  6→// - state.json: Questions from Claude Code
  7→// - answer.json: User responses back to Claude
  8→// - cognitive_substrate.usda: USD cognitive profile
  9→//
 10→// CRITICAL: USD Stage Actor does NOT auto-reload files.
 11→// We must trigger SetRootLayer() manually on file change.
 12→
 13→#pragma once
 14→
 15→#include "CoreMinimal.h"
 16→#include "Components/ActorComponent.h"
 17→#include "Dom/JsonObject.h"
 18→#include "BridgeComponent.generated.h"
 19→
 20→// Forward declare for editor-only directory watcher
 21→#if WITH_DIRECTORY_WATCHER
 22→struct FFileChangeData;
 23→#endif
 24→
 25→// Note: USD Stage Actor integration is handled via Blueprint
 26→// The OnUsdUpdated delegate notifies when cognitive_substrate.usda changes
 27→
 28→// Delegate for question received from Claude Code
 29→DECLARE_DYNAMIC_MULTICAST_DELEGATE_OneParam(FOnQuestionReceived, const FString&, QuestionJson);
 30→
 31→// Delegate for transition command
 32→DECLARE_DYNAMIC_MULTICAST_DELEGATE_TwoParams(FOnTransitionReceived, const FString&, Direction, const FString&, NextScene);
 33→
 34→// Delegate for finale
 35→DECLARE_DYNAMIC_MULTICAST_DELEGATE_OneParam(FOnFinaleReceived, const FString&, UsdPath);
 36→
 37→// Delegate for USD file update
 38→DECLARE_DYNAMIC_MULTICAST_DELEGATE(FOnUsdUpdated);
 39→
 40→// Delegate for ready state
 41→DECLARE_DYNAMIC_MULTICAST_DELEGATE_OneParam(FOnBridgeReady, int32, TotalQuestions);
