 98→    /** Fired when cognitive_substrate.usda updates */
 99→    UPROPERTY(BlueprintAssignable, Category = "Translators Bridge")
100→    FOnUsdUpdated OnUsdUpdated;
101→
102→    /** Fired when Claude Code is ready to start */
103→    UPROPERTY(BlueprintAssignable, Category = "Translators Bridge")
104→    FOnBridgeReady OnBridgeReady;
105→
106→    // === BLUEPRINT CALLABLE FUNCTIONS ===
107→
108→    /** Send acknowledgment that UE5 is ready */
109→    UFUNCTION(BlueprintCallable, Category = "Translators Bridge")
110→    void SendAcknowledge();
111→
112→    /** Send user's answer to Claude Code */
113→    UFUNCTION(BlueprintCallable, Category = "Translators Bridge")
114→    void SendAnswer(const FString& QuestionId, int32 OptionIndex, float ResponseTimeMs);
115→
116→    /** Parse current question into structured data */
117→    UFUNCTION(BlueprintCallable, Category = "Translators Bridge")
118→    FTranslatorsQuestion GetCurrentQuestion() const;
119→
120→    /** Force reload the USD stage (use if auto-detection fails) */
121→    UFUNCTION(BlueprintCallable, Category = "Translators Bridge")
122→    void ForceReloadUsdStage();
123→
124→    /** Check if bridge is connected */
125→    UFUNCTION(BlueprintCallable, Category = "Translators Bridge")
126→    bool IsBridgeConnected() const { return bIsConnected; }
127→
128→    /** Check if using USD mode (v2.0.0) */
129→    UFUNCTION(BlueprintCallable, Category = "Translators Bridge")
130→    bool IsUsingUsdMode() const { return bUsingUsdMode; }
131→
132→    /** Send acknowledgment via USD (v2.0.0) */
133→    UFUNCTION(BlueprintCallable, Category = "Translators Bridge")
