135→
136→    /** Send answer via USD (v2.0.0) */
137→    UFUNCTION(BlueprintCallable, Category = "Translators Bridge")
138→    void SendAnswerUsda(const FString& QuestionId, int32 OptionIndex, float ResponseTimeMs);
139→
140→    // === CONFIGURATION ===
141→
142→    /** Bridge directory path (default: ~/.translators) */
143→    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Translators Bridge")
144→    FString BridgePath;
145→
146→    /** Enable verbose logging */
147→    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Translators Bridge")
148→    bool bVerboseLogging = false;
149→
150→    /** Debounce time in seconds for file change detection */
151→    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Translators Bridge")
152→    float DebounceTime = 0.05f;
