154→private:
155→    // === FILE WATCHING ===
156→
157→    void SetupFileWatcher();
158→    void TeardownFileWatcher();
159→
160→#if WITH_DIRECTORY_WATCHER
161→    void OnDirectoryChanged(const TArray<FFileChangeData>& Changes);
162→#endif
163→
164→    // === STATE HANDLING ===
165→
166→    void ProcessStateFile();
167→    void HandleReadyState(const TSharedPtr<FJsonObject>& JsonObj);
168→    void HandleQuestionState(const TSharedPtr<FJsonObject>& JsonObj);
169→    void HandleTransitionState(const TSharedPtr<FJsonObject>& JsonObj);
170→    void HandleFinaleState(const TSharedPtr<FJsonObject>& JsonObj);
171→
172→    // === USD NATIVE COMMUNICATION (v2.0.0) ===
173→
174→    bool ProcessBridgeStateUsda();
175→    FString ParseUsdaVariant(const FString& Content, const FString& VariantSetName);
176→    FString ParseUsdaAttribute(const FString& Content, const FString& PrimPath, const FString& AttrName);
177→    void HandleUsdaReadyState(const FString& Content);
178→    void HandleUsdaQuestionState(const FString& Content);
179→    void HandleUsdaTransitionState(const FString& Content);
180→    void HandleUsdaFinaleState(const FString& Content);
181→    FString BuildQuestionJson();
182→    FString UpdateUsdaVariant(const FString& Content, const FString& VariantSetName, const FString& NewValue);
183→    FString UpdateUsdaAttribute(const FString& Content, const FString& PrimName, const FString& AttrName, const FString& NewValue, bool bIsString);
184→    void UpdateBehavioralSignals(FString& Content, float ResponseTimeMs);
185→
186→    // === USD PROFILE HANDLING ===
187→
188→    void OnUsdFileChanged();
189→    void ReloadUsdStage();
190→
191→    // === UTILITY ===
192→
193→    void WriteJsonToFile(const FString& Filename, const TSharedPtr<FJsonObject>& JsonObj);
194→    FString GetBridgeFilePath(const FString& Filename) const;
195→    void BridgeLog(const FString& Message) const;
196→
197→    // === STATE ===
198→
199→#if WITH_DIRECTORY_WATCHER
200→    FDelegateHandle WatchHandle;
201→#endif
202→
203→    bool bIsConnected = false;
204→    bool bUsePolling = false;
205→    bool bUsingUsdMode = false;  // v2.0.0: USD-native mode active
206→
207→    // Debouncing
208→    float TimeSinceLastStateChange = 0.0f;
209→    bool bStateChangePending = false;
210→    float TimeSinceLastUsdChange = 0.0f;
211→    bool bUsdChangePending = false;
212→
213→    // Polling (non-editor fallback)
214→    float PollTimer = 0.0f;
215→    float PollInterval = 0.5f;
216→    FDateTime LastStateFileTime;
217→
218→    // Current state
219→    FString CurrentStateJson;
220→    FTranslatorsQuestion CurrentQuestion;
221→
222→    // === BEHAVIORAL SIGNALS (v2.0.0 ADHD_MoE routing) ===
223→
224→    TArray<float> ResponseTimes;  // Track response times for pattern detection
225→    int32 HesitationCount = 0;    // Count of long hesitations (>10s)
226→    int32 RapidClickCount = 0;    // Count of rapid clicks (<500ms)
227→    int32 SkipCount = 0;          // Count of skipped questions
228→    int32 BackNavigationCount = 0; // Count of back navigations
229→};
