  24→{
  25→    PrimaryComponentTick.bCanEverTick = true;
  26→
  27→    // Default path: ~/.translators on Windows/Linux/Mac
  28→    BridgePath = FPaths::Combine(FPlatformProcess::UserHomeDir(), TEXT(".translators"));
