  32→void UBridgeComponent::BeginPlay()
  33→{
  34→    Super::BeginPlay();
  35→
  36→    BridgeLog(TEXT("========================================"));
  37→    BridgeLog(TEXT("TRANSLATORS BRIDGE COMPONENT v2.0.0"));
  38→    BridgeLog(TEXT("USD-native communication with JSON fallback"));
  39→    BridgeLog(FString::Printf(TEXT("Bridge Path: %s"), *BridgePath));
  40→    BridgeLog(TEXT("========================================"));
  41→
  42→    // Ensure bridge directory exists
  43→    IPlatformFile& PlatformFile = FPlatformFileManager::Get().GetPlatformFile();
  44→    if (!PlatformFile.DirectoryExists(*BridgePath))
  45→    {
  46→        PlatformFile.CreateDirectory(*BridgePath);
  47→        BridgeLog(FString::Printf(TEXT("Created bridge directory: %s"), *BridgePath));
  48→    }
  49→
  50→    SetupFileWatcher();
  51→
  52→    // Check for existing state files (Claude Code may have started first)
  53→    // Prefer USD over JSON
  54→    FString UsdFilePath = GetBridgeFilePath(TEXT("bridge_state.usda"));
  55→    FString JsonFilePath = GetBridgeFilePath(TEXT("state.json"));
  56→
  57→    if (PlatformFile.FileExists(*UsdFilePath))
  58→    {
  59→        BridgeLog(TEXT("Found existing bridge_state.usda - processing..."));
  60→        ProcessStateFile();
  61→    }
  62→    else if (PlatformFile.FileExists(*JsonFilePath))
  63→    {
  64→        BridgeLog(TEXT("Found existing state.json - processing..."));
  65→        ProcessStateFile();
  66→    }
  67→}
