  70→void UBridgeComponent::EndPlay(const EEndPlayReason::Type EndPlayReason)
  71→{
  72→    TeardownFileWatcher();
  73→
  74→    BridgeLog(TEXT("TRANSLATORS BRIDGE COMPONENT STOPPED"));
  75→
  76→    Super::EndPlay(EndPlayReason);
  77→}
