  80→void UBridgeComponent::TickComponent(float DeltaTime, ELevelTick TickType, FActorComponentTickFunction* ThisTickFunction)
  81→{
  82→    Super::TickComponent(DeltaTime, TickType, ThisTickFunction);
  83→
  84→    // Polling fallback for non-editor builds
  85→    if (bUsePolling)
  86→    {
  87→        PollTimer += DeltaTime;
  88→        if (PollTimer >= PollInterval)
  89→        {
  90→            PollTimer = 0.0f;
  91→
  92→            FString StateFilePath = GetBridgeFilePath(TEXT("state.json"));
  93→            IPlatformFile& PlatformFile = FPlatformFileManager::Get().GetPlatformFile();
  94→
  95→            if (PlatformFile.FileExists(*StateFilePath))
  96→            {
  97→                FDateTime ModTime = PlatformFile.GetTimeStamp(*StateFilePath);
  98→                if (ModTime > LastStateFileTime)
  99→                {
 100→                    LastStateFileTime = ModTime;
 101→                    bStateChangePending = true;
 102→                    TimeSinceLastStateChange = 0.0f;
 103→                }
 104→            }
 105→        }
 106→    }
 107→
 108→    // Debounced state file processing
 109→    if (bStateChangePending)
 110→    {
 111→        TimeSinceLastStateChange += DeltaTime;
 112→        if (TimeSinceLastStateChange >= DebounceTime)
 113→        {
 114→            bStateChangePending = false;
 115→            ProcessStateFile();
 116→        }
 117→    }
 118→
 119→    // Debounced USD file processing
 120→    if (bUsdChangePending)
 121→    {
 122→        TimeSinceLastUsdChange += DeltaTime;
 123→        if (TimeSinceLastUsdChange >= DebounceTime)
 124→        {
 125→            bUsdChangePending = false;
 126→            OnUsdFileChanged();
 127→        }
 128→    }
 129→}
