 134→void UBridgeComponent::SetupFileWatcher()
 135→{
 136→#if WITH_DIRECTORY_WATCHER
 137→    FDirectoryWatcherModule& DirWatcherModule =
 138→        FModuleManager::LoadModuleChecked<FDirectoryWatcherModule>(TEXT("DirectoryWatcher"));
 139→    IDirectoryWatcher* DirWatcher = DirWatcherModule.Get();
 140→
 141→    if (!DirWatcher)
 142→    {
 143→        BridgeLog(TEXT("ERROR: Could not get DirectoryWatcher module"));
 144→        return;
 145→    }
 146→
 147→    IDirectoryWatcher::FDirectoryChanged Callback =
 148→        IDirectoryWatcher::FDirectoryChanged::CreateUObject(
 149→            this, &UBridgeComponent::OnDirectoryChanged);
 150→
 151→    uint32 WatchFlags = 0; // No special flags needed
 152→
 153→    bool bSuccess = DirWatcher->RegisterDirectoryChangedCallback_Handle(
 154→        BridgePath, Callback, WatchHandle, WatchFlags);
 155→
 156→    if (bSuccess)
 157→    {
 158→        BridgeLog(FString::Printf(TEXT("File watcher registered for: %s"), *BridgePath));
 159→    }
 160→    else
 161→    {
 162→        BridgeLog(TEXT("ERROR: Failed to register file watcher"));
 163→    }
 164→#else
 165→    // Non-editor: Use polling in TickComponent
 166→    BridgeLog(TEXT("DirectoryWatcher not available - using file polling"));
 167→    bUsePolling = true;
 168→#endif
 169→}
