 172→void UBridgeComponent::TeardownFileWatcher()
 173→{
 174→#if WITH_DIRECTORY_WATCHER
 175→    if (WatchHandle.IsValid())
 176→    {
 177→        FDirectoryWatcherModule& DirWatcherModule =
 178→            FModuleManager::LoadModuleChecked<FDirectoryWatcherModule>(TEXT("DirectoryWatcher"));
 179→        IDirectoryWatcher* DirWatcher = DirWatcherModule.Get();
 180→
 181→        if (DirWatcher)
 182→        {
 183→            DirWatcher->UnregisterDirectoryChangedCallback_Handle(BridgePath, WatchHandle);
 184→            BridgeLog(TEXT("File watcher unregistered"));
 185→        }
 186→    }
 187→#endif
 188→}
