 191→#if WITH_DIRECTORY_WATCHER
 192→void UBridgeComponent::OnDirectoryChanged(const TArray<FFileChangeData>& Changes)
 193→{
 194→    for (const FFileChangeData& Change : Changes)
 195→    {
 196→        if (bVerboseLogging)
 197→        {
 198→            BridgeLog(FString::Printf(TEXT("File changed: %s"), *Change.Filename));
 199→        }
 200→
 201→        // State file changes (JSON or USD bridge state)
 202→        if (Change.Filename.EndsWith(TEXT("state.json")) ||
 203→            Change.Filename.EndsWith(TEXT("bridge_state.usda")))
 204→        {
 205→            // Debounce state file changes
 206→            TimeSinceLastStateChange = 0.0f;
 207→            bStateChangePending = true;
 208→        }
 209→        // USD cognitive profile changes (separate from bridge state)
 210→        else if (Change.Filename.EndsWith(TEXT("cognitive_profile.usda")) ||
 211→                 Change.Filename.EndsWith(TEXT("cognitive_substrate.usda")))
 212→        {
 213→            // Debounce USD profile file changes
 214→            TimeSinceLastUsdChange = 0.0f;
 215→            bUsdChangePending = true;
 216→        }
 217→    }
 218→}
 219→#endif
