 222→// === STATE HANDLING ===
 223→
 224→void UBridgeComponent::ProcessStateFile()
 225→{
 226→    // Try USD mode first (v2.0.0)
 227→    FString UsdFilePath = GetBridgeFilePath(TEXT("bridge_state.usda"));
 228→    IPlatformFile& PlatformFile = FPlatformFileManager::Get().GetPlatformFile();
 229→
 230→    if (PlatformFile.FileExists(*UsdFilePath))
 231→    {
 232→        if (ProcessBridgeStateUsda())
 233→        {
 234→            return; // Successfully processed USD
 235→        }
 236→    }
 237→
 238→    // Fall back to JSON mode (v1.0.0)
 239→    FString FilePath = GetBridgeFilePath(TEXT("state.json"));
 240→    FString Content;
 241→
 242→    if (!FFileHelper::LoadFileToString(Content, *FilePath))
 243→    {
 244→        if (bVerboseLogging)
 245→        {
 246→            BridgeLog(TEXT("Could not read state.json or bridge_state.usda"));
 247→        }
 248→        return;
 249→    }
 250→
 251→    // Parse JSON
 252→    TSharedPtr<FJsonObject> JsonObj;
 253→    TSharedRef<TJsonReader<>> Reader = TJsonReaderFactory<>::Create(Content);
 254→
 255→    if (!FJsonSerializer::Deserialize(Reader, JsonObj) || !JsonObj.IsValid())
 256→    {
 257→        BridgeLog(TEXT("ERROR: Invalid JSON in state.json"));
 258→        return;
 259→    }
 260→
 261→    CurrentStateJson = Content;
 262→    bUsingUsdMode = false;
 263→
 264→    // Route by type
 265→    FString StateType;
 266→    if (JsonObj->TryGetStringField(TEXT("type"), StateType))
 267→    {
 268→        if (StateType == TEXT("ready"))
 269→        {
 270→            HandleReadyState(JsonObj);
 271→        }
 272→        else if (StateType == TEXT("question"))
 273→        {
 274→            HandleQuestionState(JsonObj);
 275→        }
 276→        else if (StateType == TEXT("transition"))
 277→        {
 278→            HandleTransitionState(JsonObj);
 279→        }
 280→        else if (StateType == TEXT("finale"))
 281→        {
 282→            HandleFinaleState(JsonObj);
 283→        }
 284→        else
 285→        {
 286→            BridgeLog(FString::Printf(TEXT("Unknown state type: %s"), *StateType));
 287→        }
 288→    }
 289→}
