 292→void UBridgeComponent::HandleReadyState(const TSharedPtr<FJsonObject>& JsonObj)
 293→{
 294→    // Support both flat and nested "ready" object
 295→    const TSharedPtr<FJsonObject>* ReadyObjPtr;
 296→    const TSharedPtr<FJsonObject>& ReadyData =
 297→        JsonObj->TryGetObjectField(TEXT("ready"), ReadyObjPtr) ? *ReadyObjPtr : JsonObj;
 298→
 299→    int32 TotalQuestions = ReadyData->GetIntegerField(TEXT("total_questions"));
 300→    FString FirstScene = ReadyData->GetStringField(TEXT("first_scene"));
 301→
 302→    BridgeLog(FString::Printf(TEXT("Claude Code ready! Total questions: %d, First scene: %s"),
 303→        TotalQuestions, *FirstScene));
 304→
 305→    bIsConnected = true;
 306→    OnBridgeReady.Broadcast(TotalQuestions);
 307→}
 308→
 309→
 310→void UBridgeComponent::HandleQuestionState(const TSharedPtr<FJsonObject>& JsonObj)
 311→{
 312→    // Protocol nests question data under "question" key, but also support flat format
 313→    const TSharedPtr<FJsonObject>* QuestionObjPtr;
 314→    const TSharedPtr<FJsonObject>& QuestionData =
 315→        JsonObj->TryGetObjectField(TEXT("question"), QuestionObjPtr) ? *QuestionObjPtr : JsonObj;
 316→
 317→    // Parse into struct
 318→    CurrentQuestion = FTranslatorsQuestion();
 319→    CurrentQuestion.Index = QuestionData->GetIntegerField(TEXT("index"));
 320→    CurrentQuestion.Total = QuestionData->GetIntegerField(TEXT("total"));
 321→    CurrentQuestion.QuestionId = QuestionData->GetStringField(TEXT("id"));
 322→    CurrentQuestion.Text = QuestionData->GetStringField(TEXT("text"));
 323→    CurrentQuestion.Scene = QuestionData->GetStringField(TEXT("scene"));
 324→
 325→    // Parse options array
 326→    const TArray<TSharedPtr<FJsonValue>>* OptionsArray;
 327→    if (QuestionData->TryGetArrayField(TEXT("options"), OptionsArray))
 328→    {
 329→        for (const TSharedPtr<FJsonValue>& OptionVal : *OptionsArray)
 330→        {
 331→            const TSharedPtr<FJsonObject>& OptionObj = OptionVal->AsObject();
 332→            if (OptionObj.IsValid())
 333→            {
 334→                CurrentQuestion.OptionLabels.Add(OptionObj->GetStringField(TEXT("label")));
 335→                CurrentQuestion.OptionDirections.Add(OptionObj->GetStringField(TEXT("direction")));
 336→            }
 337→        }
 338→    }
 339→
 340→    BridgeLog(FString::Printf(TEXT("Question %d/%d: %s"),
 341→        CurrentQuestion.Index + 1, CurrentQuestion.Total, *CurrentQuestion.QuestionId));
 342→
 343→    // Broadcast raw JSON for flexible handling
 344→    OnQuestionReceived.Broadcast(CurrentStateJson);
 345→}
