 348→void UBridgeComponent::HandleTransitionState(const TSharedPtr<FJsonObject>& JsonObj)
 349→{
 350→    const TSharedPtr<FJsonObject>* TransObjPtr;
 351→    const TSharedPtr<FJsonObject>& TransData =
 352→        JsonObj->TryGetObjectField(TEXT("transition"), TransObjPtr) ? *TransObjPtr : JsonObj;
 353→
 354→    FString Direction = TransData->GetStringField(TEXT("direction"));
 355→    FString NextScene = TransData->GetStringField(TEXT("next_scene"));
 356→    float Progress = TransData->GetNumberField(TEXT("progress"));
 357→
 358→    BridgeLog(FString::Printf(TEXT("Transition: %s -> %s (%.0f%%)"),
 359→        *Direction, *NextScene, Progress * 100.0f));
 360→
 361→    OnTransitionReceived.Broadcast(Direction, NextScene);
 362→}
 363→
 364→
 365→void UBridgeComponent::HandleFinaleState(const TSharedPtr<FJsonObject>& JsonObj)
 366→{
 367→    const TSharedPtr<FJsonObject>* FinaleObjPtr;
 368→    const TSharedPtr<FJsonObject>& FinaleData =
 369→        JsonObj->TryGetObjectField(TEXT("finale"), FinaleObjPtr) ? *FinaleObjPtr : JsonObj;
 370→
 371→    FString UsdPath = FinaleData->GetStringField(TEXT("usd_path"));
 372→    FString Message = FinaleData->GetStringField(TEXT("message"));
 373→
 374→    BridgeLog(FString::Printf(TEXT("FINALE: %s"), *Message));
 375→    BridgeLog(FString::Printf(TEXT("USD Path: %s"), *UsdPath));
 376→
 377→    OnFinaleReceived.Broadcast(UsdPath);
 378→}
