 391→void UBridgeComponent::ReloadUsdStage()
 392→{
 393→    // USD Stage reload is handled via Blueprint event OnUsdUpdated
 394→    // Blueprints can call the USD Stage Actor's reload methods directly
 395→    // This avoids C++ dependency on USDImporter module at runtime
 396→
 397→    BridgeLog(TEXT("USD file changed - Broadcast OnUsdUpdated for Blueprint handling"));
 398→
 399→    // The OnUsdUpdated delegate has already been broadcast in OnUsdFileChanged()
 400→    // Blueprint implementations should handle the actual reload
