 457→
 458→void UBridgeComponent::WriteJsonToFile(const FString& Filename, const TSharedPtr<FJsonObject>& JsonObj)
 459→{
 460→    FString FilePath = GetBridgeFilePath(Filename);
 461→    FString OutputString;
 462→
 463→    TSharedRef<TJsonWriter<>> Writer = TJsonWriterFactory<>::Create(&OutputString);
 464→    FJsonSerializer::Serialize(JsonObj.ToSharedRef(), Writer);
 465→
 466→    // Write with retry logic (file may be locked by Claude Code reading it)
 467→    int32 MaxRetries = 3;
 468→    for (int32 Retry = 0; Retry < MaxRetries; ++Retry)
 469→    {
 470→        if (FFileHelper::SaveStringToFile(OutputString, *FilePath))
 471→        {
 472→            return; // Success
 473→        }
 474→
 475→        if (Retry < MaxRetries - 1)
 476→        {
 477→            BridgeLog(FString::Printf(TEXT("Write failed, retry %d/%d..."), Retry + 1, MaxRetries));
 478→            FPlatformProcess::Sleep(0.1f);
 479→        }
 480→    }
 481→
 482→    BridgeLog(FString::Printf(TEXT("ERROR: Failed to write %s after %d retries"), *Filename, MaxRetries));
 483→}
