 507→bool UBridgeComponent::ProcessBridgeStateUsda()
 508→{
 509→    FString FilePath = GetBridgeFilePath(TEXT("bridge_state.usda"));
 510→    FString Content;
 511→
 512→    if (!FFileHelper::LoadFileToString(Content, *FilePath))
 513→    {
 514→        return false;
 515→    }
 516→
 517→    // Parse sync_status variant
 518→    FString SyncStatus = ParseUsdaVariant(Content, TEXT("sync_status"));
 519→    FString MessageType = ParseUsdaVariant(Content, TEXT("message_type"));
 520→
 521→    if (bVerboseLogging)
 522→    {
 523→        BridgeLog(FString::Printf(TEXT("USD sync_status=%s, message_type=%s"), *SyncStatus, *MessageType));
 524→    }
 525→
 526→    // Route based on message type
 527→    if (MessageType == TEXT("ready"))
 528→    {
 529→        HandleUsdaReadyState(Content);
 530→    }
 531→    else if (MessageType == TEXT("question") && SyncStatus == TEXT("question_pending"))
 532→    {
 533→        HandleUsdaQuestionState(Content);
 534→    }
 535→    else if (MessageType == TEXT("transition"))
 536→    {
 537→        HandleUsdaTransitionState(Content);
 538→    }
 539→    else if (MessageType == TEXT("finale"))
 540→    {
 541→        HandleUsdaFinaleState(Content);
 542→    }
 543→
 544→    return true;
 545→}
