 548→FString UBridgeComponent::ParseUsdaVariant(const FString& Content, const FString& VariantSetName)
 549→{
 550→    // Parse variant selection from: variants = { string variantName = "value" }
 551→    FString Pattern = FString::Printf(TEXT("string %s = \"([^\"]*)\""), *VariantSetName);
 552→    FRegexPattern RegexPattern(Pattern);
 553→    FRegexMatcher Matcher(RegexPattern, Content);
 554→
 555→    if (Matcher.FindNext())
 556→    {
 557→        return Matcher.GetCaptureGroup(1);
 558→    }
 559→    return TEXT("");
 560→}
