 562→
 563→FString UBridgeComponent::ParseUsdaAttribute(const FString& Content, const FString& PrimPath, const FString& AttrName)
 564→{
 565→    // Find the prim section and extract attribute value
 566→    // This is a simplified parser - handles basic string/int/float attributes
 567→
 568→    // First find the prim section
 569→    FString PrimPattern = FString::Printf(TEXT("def [^\"]*\"%s\"[^{]*\\{([^}]*)\\}"), *PrimPath);
 570→    FRegexPattern PrimRegex(PrimPattern);
 571→    FRegexMatcher PrimMatcher(PrimRegex, Content);
 572→
 573→    FString PrimContent;
 574→    if (PrimMatcher.FindNext())
 575→    {
 576→        PrimContent = PrimMatcher.GetCaptureGroup(1);
 577→    }
 578→    else
 579→    {
 580→        // Try finding nested prim
 581→        PrimContent = Content;
 582→    }
 583→
 584→    // Parse string attribute
 585→    FString StringPattern = FString::Printf(TEXT("string %s = \"([^\"]*)\""), *AttrName);
 586→    FRegexPattern StringRegex(StringPattern);
 587→    FRegexMatcher StringMatcher(StringRegex, PrimContent);
 588→    if (StringMatcher.FindNext())
 589→    {
 590→        return StringMatcher.GetCaptureGroup(1);
 591→    }
 592→
 593→    // Parse int attribute
 594→    FString IntPattern = FString::Printf(TEXT("int %s = (-?\\d+)"), *AttrName);
 595→    FRegexPattern IntRegex(IntPattern);
 596→    FRegexMatcher IntMatcher(IntRegex, PrimContent);
 597→    if (IntMatcher.FindNext())
 598→    {
 599→        return IntMatcher.GetCaptureGroup(1);
 600→    }
 601→
 602→    // Parse float/double attribute
 603→    FString FloatPattern = FString::Printf(TEXT("(?:float|double) %s = ([\\d.]+)"), *AttrName);
 604→    FRegexPattern FloatRegex(FloatPattern);
 605→    FRegexMatcher FloatMatcher(FloatRegex, PrimContent);
 606→    if (FloatMatcher.FindNext())
 607→    {
 608→        return FloatMatcher.GetCaptureGroup(1);
 609→    }
 610→
 611→    return TEXT("");
 612→}
