 630→void UBridgeComponent::HandleUsdaQuestionState(const FString& Content)
 631→{
 632→    // Parse Message prim
 633→    CurrentQuestion = FTranslatorsQuestion();
 634→    CurrentQuestion.Index = FCString::Atoi(*ParseUsdaAttribute(Content, TEXT("Message"), TEXT("index")));
 635→    CurrentQuestion.Total = FCString::Atoi(*ParseUsdaAttribute(Content, TEXT("Message"), TEXT("total")));
 636→    CurrentQuestion.QuestionId = ParseUsdaAttribute(Content, TEXT("Message"), TEXT("question_id"));
 637→    CurrentQuestion.Text = ParseUsdaAttribute(Content, TEXT("Message"), TEXT("text"));
 638→    CurrentQuestion.Scene = ParseUsdaAttribute(Content, TEXT("Message"), TEXT("scene"));
 639→
 640→    // Parse Options
 641→    for (int32 i = 0; i < 3; ++i)
 642→    {
 643→        FString OptionPrim = FString::Printf(TEXT("Option_%d"), i);
 644→        FString Label = ParseUsdaAttribute(Content, OptionPrim, TEXT("label"));
 645→        FString Direction = ParseUsdaAttribute(Content, OptionPrim, TEXT("direction"));
 646→
 647→        if (!Label.IsEmpty())
 648→        {
 649→            CurrentQuestion.OptionLabels.Add(Label);
 650→            CurrentQuestion.OptionDirections.Add(Direction);
 651→        }
 652→    }
 653→
 654→    BridgeLog(FString::Printf(TEXT("USD Question %d/%d: %s"),
 655→        CurrentQuestion.Index + 1, CurrentQuestion.Total, *CurrentQuestion.QuestionId));
 656→
 657→    // Build JSON for backward-compatible delegate
 658→    CurrentStateJson = BuildQuestionJson();
 659→    OnQuestionReceived.Broadcast(CurrentStateJson);
 660→}
