 718→void UBridgeComponent::SendAnswerUsda(const FString& QuestionId, int32 OptionIndex, float ResponseTimeMs)
 719→{
 720→    FString FilePath = GetBridgeFilePath(TEXT("bridge_state.usda"));
 721→    FString Content;
 722→
 723→    if (!FFileHelper::LoadFileToString(Content, *FilePath))
 724→    {
 725→        BridgeLog(TEXT("ERROR: Could not read bridge_state.usda for answer"));
 726→        // Fall back to JSON
 727→        SendAnswer(QuestionId, OptionIndex, ResponseTimeMs);
 728→        return;
 729→    }
 730→
 731→    FString Timestamp = FDateTime::UtcNow().ToIso8601();
 732→    FString SelectedLabel = (OptionIndex >= 0 && OptionIndex < CurrentQuestion.OptionLabels.Num())
 733→        ? CurrentQuestion.OptionLabels[OptionIndex] : TEXT("");
 734→    FString SelectedDirection = (OptionIndex >= 0 && OptionIndex < CurrentQuestion.OptionDirections.Num())
 735→        ? CurrentQuestion.OptionDirections[OptionIndex] : TEXT("");
 736→
 737→    // Update sync_status variant to "answer_received"
 738→    Content = UpdateUsdaVariant(Content, TEXT("sync_status"), TEXT("answer_received"));
 739→    Content = UpdateUsdaVariant(Content, TEXT("message_type"), TEXT("answer"));
 740→
 741→    // Update Answer prim attributes
 742→    Content = UpdateUsdaAttribute(Content, TEXT("Answer"), TEXT("question_id"), QuestionId, true);
 743→    Content = UpdateUsdaAttribute(Content, TEXT("Answer"), TEXT("option_index"), FString::FromInt(OptionIndex), false);
 744→    Content = UpdateUsdaAttribute(Content, TEXT("Answer"), TEXT("response_time_ms"), FString::SanitizeFloat(ResponseTimeMs), false);
 745→    Content = UpdateUsdaAttribute(Content, TEXT("Answer"), TEXT("selected_label"), SelectedLabel, true);
 746→    Content = UpdateUsdaAttribute(Content, TEXT("Answer"), TEXT("selected_direction"), SelectedDirection, true);
 747→    Content = UpdateUsdaAttribute(Content, TEXT("Answer"), TEXT("timestamp"), Timestamp, true);
 748→
 749→    // Update behavioral signals
 750→    UpdateBehavioralSignals(Content, ResponseTimeMs);
 751→
 752→    // Write back
 753→    int32 MaxRetries = 3;
 754→    for (int32 Retry = 0; Retry < MaxRetries; ++Retry)
 755→    {
 756→        if (FFileHelper::SaveStringToFile(Content, *FilePath))
 757→        {
 758→            BridgeLog(FString::Printf(TEXT("USD answer sent: %s = option %d (%.0fms)"),
 759→                *QuestionId, OptionIndex, ResponseTimeMs));
 760→            return;
 761→        }
 762→        FPlatformProcess::Sleep(0.1f);
 763→    }
 764→
 765→    BridgeLog(TEXT("ERROR: Failed to write USD answer, falling back to JSON"));
 766→    SendAnswer(QuestionId, OptionIndex, ResponseTimeMs);
 767→}
