 770→FString UBridgeComponent::UpdateUsdaVariant(const FString& Content, const FString& VariantSetName, const FString& NewValue)
 771→{
 772→    // Simple string replacement for variant - more reliable than regex
 773→    FString SearchPattern = FString::Printf(TEXT("string %s = \""), *VariantSetName);
 774→    int32 StartIdx = Content.Find(SearchPattern);
 775→    if (StartIdx == INDEX_NONE)
 776→    {
 777→        return Content;
 778→    }
 779→
 780→    StartIdx += SearchPattern.Len();
 781→    int32 EndIdx = Content.Find(TEXT("\""), ESearchCase::CaseSensitive, ESearchDir::FromStart, StartIdx);
 782→    if (EndIdx == INDEX_NONE)
 783→    {
 784→        return Content;
 785→    }
 786→
 787→    // Build new content
 788→    FString Result = Content.Left(StartIdx) + NewValue + Content.Mid(EndIdx);
 789→    return Result;
 790→}
