 792→
 793→FString UBridgeComponent::UpdateUsdaAttribute(const FString& Content, const FString& PrimName, const FString& AttrName, const FString& NewValue, bool bIsString)
 794→{
 795→    // Find attribute pattern and replace value
 796→    // For string: string attrName = "value"
 797→    // For numeric: int/float/double attrName = value
 798→
 799→    FString Result = Content;
 800→
 801→    if (bIsString)
 802→    {
 803→        // Find: string attrName = "..."
 804→        FString SearchPattern = FString::Printf(TEXT("string %s = \""), *AttrName);
 805→        int32 StartIdx = Result.Find(SearchPattern);
 806→        if (StartIdx != INDEX_NONE)
 807→        {
 808→            StartIdx += SearchPattern.Len();
 809→            int32 EndIdx = Result.Find(TEXT("\""), ESearchCase::CaseSensitive, ESearchDir::FromStart, StartIdx);
 810→            if (EndIdx != INDEX_NONE)
 811→            {
 812→                FString EscapedValue = NewValue.Replace(TEXT("\\"), TEXT("\\\\")).Replace(TEXT("\""), TEXT("\\\""));
 813→                Result = Result.Left(StartIdx) + EscapedValue + Result.Mid(EndIdx);
 814→            }
 815→        }
 816→    }
 817→    else
 818→    {
 819→        // Find numeric attributes: int/float/double attrName = value
 820→        TArray<FString> TypePrefixes = { TEXT("int"), TEXT("float"), TEXT("double"), TEXT("bool") };
 821→
 822→        for (const FString& TypePrefix : TypePrefixes)
 823→        {
 824→            FString SearchPattern = FString::Printf(TEXT("%s %s = "), *TypePrefix, *AttrName);
 825→            int32 StartIdx = Result.Find(SearchPattern);
 826→            if (StartIdx != INDEX_NONE)
 827→            {
 828→                StartIdx += SearchPattern.Len();
 829→                // Find end of value (newline or space or semicolon)
 830→                int32 EndIdx = StartIdx;
 831→                while (EndIdx < Result.Len())
 832→                {
 833→                    TCHAR C = Result[EndIdx];
 834→                    if (C == '\n' || C == '\r' || C == ';' || C == ' ' || C == '\t')
 835→                    {
 836→                        break;
 837→                    }
 838→                    EndIdx++;
 839→                }
 840→                Result = Result.Left(StartIdx) + NewValue + Result.Mid(EndIdx);
 841→                break;
 842→            }
 843→        }
 844→    }
 845→
 846→    return Result;
 847→}
