 849→
 850→void UBridgeComponent::UpdateBehavioralSignals(FString& Content, float ResponseTimeMs)
 851→{
 852→    // ═══════════════════════════════════════════════════════════════════════════════
 853→    // THINKINGMACHINES [He2025] BATCH-INVARIANCE COMPLIANT
 854→    // Same signals → Same routing → Same behavior
 855→    // FIXED thresholds ensure deterministic expert selection regardless of load
 856→    // ═══════════════════════════════════════════════════════════════════════════════
 857→
 858→    // PHASE 1: DETECT - Collect signals
 859→    ResponseTimes.Add(ResponseTimeMs);
 860→
 861→    // Calculate average response time (FIXED algorithm - sum/count)
 862→    float TotalTime = 0.0f;
 863→    for (float Time : ResponseTimes)
 864→    {
 865→        TotalTime += Time;
 866→    }
 867→    float AvgResponseTime = ResponseTimes.Num() > 0 ? TotalTime / ResponseTimes.Num() : 0.0f;
 868→
 869→    // FIXED THRESHOLDS (batch-invariant - same across all sessions)
 870→    const float HESITATION_THRESHOLD_MS = 10000.0f;   // 10 seconds
 871→    const float RAPID_CLICK_THRESHOLD_MS = 500.0f;    // 0.5 seconds
 872→    const float DEPLETED_AVG_THRESHOLD_MS = 15000.0f; // 15 seconds average
 873→    const int32 HESITATION_COUNT_THRESHOLD = 2;
 874→    const int32 RAPID_CLICK_COUNT_THRESHOLD = 3;
 875→
 876→    // Detect hesitation
 877→    bool bLongHesitation = ResponseTimeMs > HESITATION_THRESHOLD_MS;
 878→    if (bLongHesitation)
 879→    {
 880→        HesitationCount++;
 881→    }
 882→
 883→    // Detect rapid clicking
 884→    bool bRapidClick = ResponseTimeMs < RAPID_CLICK_THRESHOLD_MS && ResponseTimes.Num() > 1;
 885→    if (bRapidClick)
 886→    {
 887→        RapidClickCount++;
 888→    }
 889→
 890→    // PHASE 2: CASCADE - ADHD_MoE FIXED PRIORITY ROUTING
 891→    // Priority: Validator(1) > Scaffolder(2) > Restorer(3) > Refocuser(4) > Celebrator(5) > Socratic(6) > Direct(7)
 892→    // First match wins - NEVER skip or reorder
 893→
 894→    FString DetectedState = TEXT("focused");
 895→    FString RecommendedExpert = TEXT("Direct");
 896→    FString BurnoutLevel = TEXT("GREEN");
 897→    FString MomentumPhase = TEXT("rolling");
 898→
 899→    // Priority 1: Validator - frustrated, RED burnout, caps, negative signals
 900→    if (RapidClickCount > RAPID_CLICK_COUNT_THRESHOLD)
 901→    {
 902→        DetectedState = TEXT("frustrated");
 903→        RecommendedExpert = TEXT("Validator");
 904→        BurnoutLevel = TEXT("RED");
 905→        MomentumPhase = TEXT("crashed");
 906→    }
 907→    // Priority 2: Scaffolder - overwhelmed, stuck, too_many signals
 908→    else if (bLongHesitation || HesitationCount > HESITATION_COUNT_THRESHOLD)
 909→    {
 910→        DetectedState = TEXT("stuck");
 911→        RecommendedExpert = TEXT("Scaffolder");
 912→        BurnoutLevel = TEXT("ORANGE");
 913→        MomentumPhase = TEXT("declining");
 914→    }
 915→    // Priority 3: Restorer - depleted, ORANGE burnout, post-crash
 916→    else if (AvgResponseTime > DEPLETED_AVG_THRESHOLD_MS)
 917→    {
 918→        DetectedState = TEXT("depleted");
 919→        RecommendedExpert = TEXT("Restorer");
 920→        BurnoutLevel = TEXT("ORANGE");
 921→        MomentumPhase = TEXT("crashed");
 922→    }
 923→    // Priority 4: Refocuser - distracted, tangent signals
 924→    else if (ResponseTimes.Num() > 3 && ResponseTimeMs > AvgResponseTime * 2.0f)
 925→    {
 926→        DetectedState = TEXT("distracted");
 927→        RecommendedExpert = TEXT("Refocuser");
 928→        BurnoutLevel = TEXT("YELLOW");
 929→        MomentumPhase = TEXT("declining");
 930→    }
 931→    // Priority 5: Celebrator - task_complete, milestone reached
 932→    else if (CurrentQuestion.Index == CurrentQuestion.Total - 1)
 933→    {
 934→        DetectedState = TEXT("completing");
 935→        RecommendedExpert = TEXT("Celebrator");
 936→        BurnoutLevel = TEXT("GREEN");
 937→        MomentumPhase = TEXT("peak");
 938→    }
 939→    // Priority 6: Socratic - exploring, high energy, "what if" signals
 940→    else if (ResponseTimes.Num() >= 2 && ResponseTimeMs > 3000.0f && ResponseTimeMs < 8000.0f)
 941→    {
 942→        DetectedState = TEXT("exploring");
 943→        RecommendedExpert = TEXT("Socratic");
 944→        BurnoutLevel = TEXT("GREEN");
 945→        MomentumPhase = TEXT("building");
 946→    }
 947→    // Priority 7: Direct - focused, hyperfocused, flow state (DEFAULT)
 948→    else
 949→    {
 950→        DetectedState = TEXT("focused");
 951→        RecommendedExpert = TEXT("Direct");
 952→        BurnoutLevel = TEXT("GREEN");
 953→        MomentumPhase = (ResponseTimes.Num() > 5) ? TEXT("rolling") : TEXT("building");
 954→    }
 955→
 956→    // PHASE 3: LOCK - Parameters locked for this response (no further changes)
 957→
 958→    // PHASE 4: EXECUTE - Update signals in USD content
 959→    Content = UpdateUsdaAttribute(Content, TEXT("BehavioralSignals"), TEXT("last_response_time_ms"), FString::SanitizeFloat(ResponseTimeMs), false);
 960→    Content = UpdateUsdaAttribute(Content, TEXT("BehavioralSignals"), TEXT("average_response_time_ms"), FString::SanitizeFloat(AvgResponseTime), false);
 961→    Content = UpdateUsdaAttribute(Content, TEXT("BehavioralSignals"), TEXT("hesitation_count"), FString::FromInt(HesitationCount), false);
 962→    Content = UpdateUsdaAttribute(Content, TEXT("BehavioralSignals"), TEXT("long_hesitation_detected"), bLongHesitation ? TEXT("true") : TEXT("false"), false);
 963→    Content = UpdateUsdaAttribute(Content, TEXT("BehavioralSignals"), TEXT("rapid_click_count"), FString::FromInt(RapidClickCount), false);
 964→    Content = UpdateUsdaAttribute(Content, TEXT("BehavioralSignals"), TEXT("detected_state"), DetectedState, true);
 965→    Content = UpdateUsdaAttribute(Content, TEXT("BehavioralSignals"), TEXT("recommended_expert"), RecommendedExpert, true);
 966→    Content = UpdateUsdaAttribute(Content, TEXT("BehavioralSignals"), TEXT("burnout_level"), BurnoutLevel, true);
 967→    Content = UpdateUsdaAttribute(Content, TEXT("BehavioralSignals"), TEXT("momentum_phase"), MomentumPhase, true);
 968→
 969→    // PHASE 5: UPDATE - Log routing decision for traceability
 970→    if (bVerboseLogging)
 971→    {
 972→        BridgeLog(FString::Printf(TEXT("[EXEC] State=%s Expert=%s Burnout=%s Momentum=%s"),
 973→            *DetectedState, *RecommendedExpert, *BurnoutLevel, *MomentumPhase));
 974→    }
 975→}
