 978→void UBridgeComponent::SendAcknowledgeUsda()
 979→{
 980→    FString FilePath = GetBridgeFilePath(TEXT("bridge_state.usda"));
 981→    FString Content;
 982→
 983→    if (!FFileHelper::LoadFileToString(Content, *FilePath))
 984→    {
 985→        BridgeLog(TEXT("USD ack: bridge_state.usda not found, sending JSON ack"));
 986→        SendAcknowledge();
 987→        return;
 988→    }
 989→
 990→    FString Timestamp = FDateTime::UtcNow().ToIso8601();
 991→
 992→    // Update message_type to "ack"
 993→    Content = UpdateUsdaVariant(Content, TEXT("message_type"), TEXT("ack"));
 994→
 995→    // Update Ack prim
 996→    Content = UpdateUsdaAttribute(Content, TEXT("Ack"), TEXT("ready"), TEXT("true"), false);
 997→    Content = UpdateUsdaAttribute(Content, TEXT("Ack"), TEXT("ue_version"), TEXT("5.7.2"), true);
 998→    Content = UpdateUsdaAttribute(Content, TEXT("Ack"), TEXT("project"), TEXT("TranslatorsCard"), true);
 999→    Content = UpdateUsdaAttribute(Content, TEXT("Ack"), TEXT("timestamp"), Timestamp, true);
1000→
1001→    if (FFileHelper::SaveStringToFile(Content, *FilePath))
1002→    {
1003→        BridgeLog(TEXT("USD acknowledgment sent"));
1004→        bUsingUsdMode = true;
1005→    }
1006→    else
1007→    {
1008→        BridgeLog(TEXT("USD ack failed, sending JSON"));
1009→        SendAcknowledge();
1010→    }
1011→}
