 58→void ATranslatorsHUD::EndPlay(const EEndPlayReason::Type EndPlayReason)
 59→{
 60→    // Unbind events
 61→    if (BridgeComponent)
 62→    {
 63→        BridgeComponent->OnBridgeReady.RemoveAll(this);
 64→        BridgeComponent->OnQuestionReceived.RemoveAll(this);
 65→        BridgeComponent->OnTransitionReceived.RemoveAll(this);
 66→        BridgeComponent->OnFinaleReceived.RemoveAll(this);
 67→    }
 68→
 69→    // Clean up widgets
 70→    if (QuestionWidget)
 71→    {
 72→        QuestionWidget->OnAnswerSelected.RemoveAll(this);
 73→        QuestionWidget->RemoveFromParent();
 74→    }
 75→    if (ConnectingWidget)
 76→    {
 77→        ConnectingWidget->RemoveFromParent();
 78→    }
 79→    if (FinaleWidget)
 80→    {
 81→        FinaleWidget->RemoveFromParent();
 82→    }
 83→
 84→    Super::EndPlay(EndPlayReason);
 85→}
