 88→UBridgeComponent* ATranslatorsHUD::FindBridgeComponent()
 89→{
 90→    // Search all actors for one with BridgeComponent
 91→    TArray<AActor*> AllActors;
 92→    UGameplayStatics::GetAllActorsOfClass(GetWorld(), AActor::StaticClass(), AllActors);
 93→
 94→    for (AActor* Actor : AllActors)
 95→    {
 96→        UBridgeComponent* Bridge = Actor->FindComponentByClass<UBridgeComponent>();
 97→        if (Bridge)
 98→        {
 99→            return Bridge;
100→        }
101→    }
102→
103→    return nullptr;
104→}
