 55→void UW_QuestionDisplay::BuildWidgetTree()
 56→{
 57→    // Create root canvas
 58→    UCanvasPanel* RootCanvas = WidgetTree->ConstructWidget<UCanvasPanel>(UCanvasPanel::StaticClass(), TEXT("RootCanvas"));
 59→    WidgetTree->RootWidget = RootCanvas;
 60→
 61→    // Create background border - centered panel
 62→    BackgroundBorder = WidgetTree->ConstructWidget<UBorder>(UBorder::StaticClass(), TEXT("BackgroundBorder"));
 63→    BackgroundBorder->SetBrushColor(BackgroundColor);
 64→    BackgroundBorder->SetPadding(FMargin(40.0f, 30.0f));
 65→
 66→    UCanvasPanelSlot* BorderSlot = RootCanvas->AddChildToCanvas(BackgroundBorder);
 67→    if (BorderSlot)
 68→    {
 69→        // Center the panel
 70→        BorderSlot->SetAnchors(FAnchors(0.5f, 0.5f, 0.5f, 0.5f));
 71→        BorderSlot->SetAlignment(FVector2D(0.5f, 0.5f));
 72→        BorderSlot->SetAutoSize(true);
 73→    }
 74→
 75→    // Create main vertical layout
 76→    UVerticalBox* MainLayout = WidgetTree->ConstructWidget<UVerticalBox>(UVerticalBox::StaticClass(), TEXT("MainLayout"));
 77→    BackgroundBorder->AddChild(MainLayout);
 78→
 79→    // Create size box to constrain width
 80→    USizeBox* ContentSizeBox = WidgetTree->ConstructWidget<USizeBox>(USizeBox::StaticClass(), TEXT("ContentSizeBox"));
 81→    ContentSizeBox->SetWidthOverride(600.0f);
 82→    UVerticalBoxSlot* SizeBoxSlot = MainLayout->AddChildToVerticalBox(ContentSizeBox);
