 84→    {
 85→        SizeBoxSlot->SetHorizontalAlignment(HAlign_Center);
 86→    }
 87→
 88→    // Inner vertical box for content
 89→    UVerticalBox* ContentBox = WidgetTree->ConstructWidget<UVerticalBox>(UVerticalBox::StaticClass(), TEXT("ContentBox"));
 90→    ContentSizeBox->AddChild(ContentBox);
 91→
 92→    // Progress text (top)
 93→    ProgressText = WidgetTree->ConstructWidget<UTextBlock>(UTextBlock::StaticClass(), TEXT("ProgressText"));
 94→    ProgressText->SetText(FText::FromString(TEXT("1 / 8")));
 95→    ProgressText->SetColorAndOpacity(FSlateColor(ProgressTextColor));
