193→void UW_QuestionDisplay::CreateOptionButtons()
194→{
195→    ClearOptions();
196→
197→    if (!OptionsContainer)
198→    {
199→        UE_LOG(LogTemp, Warning, TEXT("[W_QuestionDisplay] No OptionsContainer"));
200→        return;
201→    }
202→
203→    TSubclassOf<UW_OptionButton> ButtonClass = OptionButtonClass;
204→    if (!ButtonClass)
205→    {
206→        ButtonClass = UW_OptionButton::StaticClass();
207→    }
208→
209→    const int32 NumOptions = CurrentQuestion.OptionLabels.Num();
210→    for (int32 i = 0; i < NumOptions; i++)
211→    {
212→        UW_OptionButton* NewButton = CreateWidget<UW_OptionButton>(this, ButtonClass);
213→        if (NewButton)
214→        {
215→            FText Label = FText::FromString(CurrentQuestion.OptionLabels[i]);
216→            FString Dir = CurrentQuestion.OptionDirections.IsValidIndex(i)
217→                ? CurrentQuestion.OptionDirections[i]
218→                : TEXT("forward");
219→
220→            NewButton->SetupOption(i, Label, Dir);
221→            NewButton->OnOptionClicked.AddDynamic(this, &UW_QuestionDisplay::HandleOptionClicked);
222→
223→            UVerticalBoxSlot* ButtonSlot = OptionsContainer->AddChildToVerticalBox(NewButton);
224→            if (ButtonSlot)
225→            {
226→                ButtonSlot->SetPadding(FMargin(0.0f, 8.0f, 0.0f, 8.0f));
227→                ButtonSlot->SetHorizontalAlignment(HAlign_Fill);
228→            }
229→
230→            OptionButtons.Add(NewButton);
231→        }
232→    }
233→}
