236→void UW_QuestionDisplay::HandleOptionClicked(int32 OptionIndex)
237→{
238→    if (SelectedOptionIndex != -1)
239→    {
240→        return;
241→    }
242→
243→    SelectedOptionIndex = OptionIndex;
244→
245→    for (int32 i = 0; i < OptionButtons.Num(); i++)
246→    {
247→        if (OptionButtons[i])
248→        {
249→            OptionButtons[i]->SetHighlighted(i == OptionIndex);
250→        }
251→    }
252→
253→    UE_LOG(LogTemp, Log, TEXT("[W_QuestionDisplay] Answer: option %d"), OptionIndex);
254→    OnAnswerSelected.Broadcast(OptionIndex);
255→}
