135→void UW_OptionButton::UpdateVisualState(const FLinearColor& BackgroundColor)
136→{
137→    if (ButtonBorder)
138→    {
139→        ButtonBorder->SetBrushColor(BackgroundColor);
140→    }
141→    else if (OptionButton)
142→    {
143→        // Fallback: tint the button itself
144→        FButtonStyle Style = OptionButton->GetStyle();
145→        Style.Normal.TintColor = FSlateColor(BackgroundColor);
146→        Style.Hovered.TintColor = FSlateColor(HoveredColor);
