153→void UW_OptionButton::BuildWidgetTree()
154→{
155→    // Create border as root (for background color)
156→    ButtonBorder = WidgetTree->ConstructWidget<UBorder>(UBorder::StaticClass(), TEXT("ButtonBorder"));
157→    ButtonBorder->SetBrushColor(NormalColor);
158→    ButtonBorder->SetPadding(FMargin(20.0f, 12.0f));
159→    WidgetTree->RootWidget = ButtonBorder;
160→
161→    // Create size box to ensure consistent button size
162→    USizeBox* ButtonSizeBox = WidgetTree->ConstructWidget<USizeBox>(USizeBox::StaticClass(), TEXT("ButtonSizeBox"));
163→    ButtonSizeBox->SetMinDesiredWidth(400.0f);
164→    ButtonSizeBox->SetMinDesiredHeight(50.0f);
165→    ButtonBorder->AddChild(ButtonSizeBox);
166→
167→    // Create the actual button (invisible, just for interaction)
168→    OptionButton = WidgetTree->ConstructWidget<UButton>(UButton::StaticClass(), TEXT("OptionButton"));
169→
170→    // Make button transparent - border handles visuals
171→    FButtonStyle TransparentStyle;
172→    TransparentStyle.Normal.TintColor = FSlateColor(FLinearColor::Transparent);
173→    TransparentStyle.Hovered.TintColor = FSlateColor(FLinearColor::Transparent);
174→    TransparentStyle.Pressed.TintColor = FSlateColor(FLinearColor::Transparent);
175→    OptionButton->SetStyle(TransparentStyle);
176→
177→    ButtonSizeBox->AddChild(OptionButton);
178→
179→    // Create label text
180→    OptionLabel = WidgetTree->ConstructWidget<UTextBlock>(UTextBlock::StaticClass(), TEXT("OptionLabel"));
181→    OptionLabel->SetText(LabelText.IsEmpty() ? FText::FromString(TEXT("Option")) : LabelText);
182→    OptionLabel->SetColorAndOpacity(FSlateColor(TextColor));
183→    OptionLabel->SetJustification(ETextJustify::Center);
184→    OptionLabel->SetAutoWrapText(true);
185→
186→    FSlateFontInfo LabelFont = OptionLabel->GetFont();
187→    LabelFont.Size = 18;
188→    OptionLabel->SetFont(LabelFont);
189→
190→    OptionButton->AddChild(OptionLabel);
191→
192→    UE_LOG(LogTemp, Log, TEXT("[W_OptionButton] Built programmatic widget tree"));
193→}
