 15→UW_ProgressIndicator::UW_ProgressIndicator(const FObjectInitializer& ObjectInitializer)
 16→    : Super(ObjectInitializer)
 17→{
 18→    TotalQuestions = 8;
 19→    CurrentQuestion = 0;
 20→
 21→    // 8-bit color scheme
 22→    CompletedColor = FLinearColor(0.36f, 1.0f, 0.86f, 1.0f);  // Cyan (#5cffdb)
 23→    IncompleteColor = FLinearColor(0.3f, 0.3f, 0.3f, 0.5f);   // Dim gray
 24→    CurrentColor = FLinearColor(1.0f, 0.8f, 0.2f, 1.0f);      // Gold
 25→}
 26→
 27→
 28→void UW_ProgressIndicator::NativeConstruct()
 29→{
 30→    Super::NativeConstruct();
 31→
 32→    // Build widget tree programmatically if not bound from Blueprint
 33→    if (!IndicatorContainer)
 34→    {
 35→        BuildWidgetTree();
 36→    }
 37→
 38→    // Create indicator images if we have a container
 39→    if (IndicatorContainer)
 40→    {
 41→        IndicatorContainer->ClearChildren();
 42→        IndicatorImages.Empty();
 43→
 44→        for (int32 i = 0; i < TotalQuestions; i++)
 45→        {
 46→            UImage* Indicator = WidgetTree->ConstructWidget<UImage>(UImage::StaticClass());
 47→            if (Indicator)
 48→            {
 49→                // Set size (small square)
 50→                Indicator->SetDesiredSizeOverride(FVector2D(12.0f, 12.0f));
 51→
 52→                // Add to container
 53→                UHorizontalBoxSlot* IndicatorSlot = IndicatorContainer->AddChildToHorizontalBox(Indicator);
 54→                if (IndicatorSlot)
 55→                {
 56→                    IndicatorSlot->SetPadding(FMargin(4.0f, 0.0f, 4.0f, 0.0f));
 57→                    IndicatorSlot->SetVerticalAlignment(VAlign_Center);
 58→                }
 59→
 60→                IndicatorImages.Add(Indicator);
 61→            }
 62→        }
 63→    }
 64→
 65→    // Initial state
 66→    RefreshIndicators();
 67→
 68→    UE_LOG(LogTemp, Log, TEXT("[W_ProgressIndicator] Constructed with %d slots"), TotalQuestions);
 69→}
