 81→
 82→void UW_ProgressIndicator::SetTotalQuestions(int32 Total)
 83→{
 84→    TotalQuestions = FMath::Max(1, Total);
 85→
 86→    // Rebuild indicators if needed
 87→    if (IndicatorImages.Num() != TotalQuestions && IndicatorContainer)
 88→    {
 89→        // Clear and rebuild
 90→        IndicatorContainer->ClearChildren();
 91→        IndicatorImages.Empty();
 92→
 93→        for (int32 i = 0; i < TotalQuestions; i++)
 94→        {
 95→            UImage* Indicator = WidgetTree->ConstructWidget<UImage>(UImage::StaticClass());
 96→            if (Indicator)
 97→            {
 98→                Indicator->SetDesiredSizeOverride(FVector2D(12.0f, 12.0f));
 99→                UHorizontalBoxSlot* IndicatorSlot = IndicatorContainer->AddChildToHorizontalBox(Indicator);
100→                if (IndicatorSlot)
101→                {
102→                    IndicatorSlot->SetPadding(FMargin(4.0f, 0.0f, 4.0f, 0.0f));
103→                }
104→                IndicatorImages.Add(Indicator);
105→            }
106→        }
107→    }
108→
109→    RefreshIndicators();
110→}
111→
112→
113→float UW_ProgressIndicator::GetCompletionPercent() const
114→{
115→    if (TotalQuestions <= 0)
116→    {
117→        return 0.0f;
118→    }
119→    return static_cast<float>(CurrentQuestion) / static_cast<float>(TotalQuestions);
120→}
121→
122→
123→void UW_ProgressIndicator::RefreshIndicators()
124→{
125→    // Update indicator colors
126→    for (int32 i = 0; i < IndicatorImages.Num(); i++)
127→    {
128→        UImage* Indicator = IndicatorImages[i];
129→        if (!Indicator) continue;
130→
131→        FLinearColor Color;
132→        if (i < CurrentQuestion)
133→        {
134→            // Completed
135→            Color = CompletedColor;
136→        }
137→        else if (i == CurrentQuestion)
138→        {
139→            // Current (in progress)
140→            Color = CurrentColor;
141→        }
142→        else
143→        {
144→            // Not yet reached
145→            Color = IncompleteColor;
146→        }
147→
148→        Indicator->SetColorAndOpacity(Color);
149→    }
150→
151→    // Update text label
152→    if (ProgressLabel)
153→    {
154→        FString LabelText = FString::Printf(TEXT("%d / %d"), CurrentQuestion, TotalQuestions);
155→        ProgressLabel->SetText(FText::FromString(LabelText));
156→    }
157→}
